from pathlib import Path
import json,html,re,math
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent
def load(n):return json.loads((OUT/n).read_text(encoding="utf-8-sig"))
i=load("inputs.json");r=load("results.json");m=load("measurements.json");v=load("verification.json")
style=re.search(r"<style>.*?</style>",(ROOT/"audits/2026-10-30-master-data-natif/index.html").read_text(encoding="utf-8"),re.S).group()
def esc(x):return html.escape(str(x))
def num(x,d=0):return f"{x:,.{d}f}".replace(",","\u202f").replace(".",",")
def table(head,rows):
 return '<div class="table-scroll" tabindex="0"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(repo,path):
 rr=m["repos"][repo];return '<a class="proof" href="https://github.com/'+rr["repository"]+'/blob/'+rr["commit"]+'/'+path+'">'+esc(Path(path).name)+'</a>'
parts=['<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Master Data comparable — quatre charges avec réutilisation</title>'+style+'<header><p>ÉTUDE ÉCONOMIQUE FLOW · 30 OCTOBRE 2026</p><h1>Le coût de la Master Data, avec réutilisation</h1><p>Quatre références natives, un même périmètre métier et un total de JH par OSS.</p><nav><a href="#resultats">Résultats</a><a href="#perimetre">Périmètre commun</a><a href="#calcul">Calcul et hypothèses</a><a href="#incertitude">Incertitude</a><a href="#activites">Activités</a><a href="#avancement">Avancement</a></nav></header><main>']
parts.append('<section id="resultats"><h2>Les quatre estimations</h2><p><strong>Il s’agit de réaliser les fonctions Master Data sur une plateforme native disponible et réutilisée sans modification.</strong> Les JH incluent les activités du projet logiciel et la qualification/intégration des composants retenus. Ils ne financent pas la reconstruction de la plateforme.</p><div class="cards">')
for x in r["results"]:
 c=x["scenarios"]["central"];lo=x["scenarios"]["lower"];hi=x["scenarios"]["upper"]
 parts.append('<article class="card"><h3>'+esc(x["label"])+'</h3><p class="value">≈ '+num(c["total_jh"])+' JH</p><p>Scénarios : <strong>'+num(math.floor(lo["total_jh"]/50)*50)+' à '+num(math.ceil(hi["total_jh"]/50)*50)+' JH</strong></p><p class="small">Calcul central : '+num(c["total_schedule_months"],1)+' mois selon le modèle.<br>Incertitude élevée ; aucun percentile.</p></article>')
parts.append('</div><p class="small">Totaux centraux arrondis au JH pour suivre le calcul ; bornes de scénarios arrondies vers l’extérieur à 50 JH. Cette précision d’affichage n’est pas une précision de prévision.</p><div class="note"><strong>Ce calcul remplace l’utilisation des anciens montants de 8 600 / 10 600 / 5 200 / 8 000 JH comme coûts Master Data.</strong> Il repart d’un périmètre corrigé et du traitement COCOMO de la réutilisation ; aucune remise forfaitaire n’est appliquée aux anciens totaux.</div><p>'+esc(i["meaning"])+' Les quatre alternatives ne s’additionnent pas.</p></section>')
parts.append('<section id="perimetre"><h2>Le même contrat métier pour les quatre références</h2><p>'+esc(i["scope"]["comparability"])+'</p>')
for contract in i["scope"]["contracts"]:
 parts.append('<article class="border"><h3>'+esc(contract["id"]+' · '+contract["name"])+'</h3><p>'+esc(contract["expected"])+'</p><p class="small">'+esc(contract["variation"])+'</p>')
 rows=[]
 for product in i["products"]:
  rows.append([esc(product["label"]),' · '.join(link(repo,path) for repo,path in contract["proofs"][product["id"]])])
 parts.append(table(["Référence","Preuves dans le code au commit figé"],rows)+'</article>')
parts.append('<h3>Les limites du périmètre</h3><ul>'+''.join('<li>'+esc(x)+'</li>' for x in i["scope"]["exclusions"])+'</ul><p><strong>La famille FLOW de six capacités n’est donc pas entièrement chiffrée ici.</strong> Le résultat porte sur sa partie commune observée dans les quatre OSS ; les garanties avancées devront faire l’objet d’un complément identifié.</p></section>')
parts.append('<section id="calcul"><h2>Comment les JH sont calculés</h2><p>Les fonctions métier sélectionnées fournissent une taille de réalisation neuve. Les mécanismes génériques fournissent une taille réutilisée, transformée en équivalent de travail neuf selon COCOMO. La reconstruction historique de ces composants n’est jamais imputée à Master Data.</p>')
rows=[]
for x in r["results"]:
 n=x["sizes"]["new"];u=x["sizes"]["reused"];c=x["scenarios"]["central"]
 rows.append([esc(x["label"]),num(n["program_units"]),num(n["declarative_units"]),num(c["reused_logical_units"]),num(c["reused_equivalent_units"],1),num(c["equivalent_KSLOC"],3),num(c["total_jh"],1)])
parts.append(table(["Référence","Code métier","Déclaratif métier","Taille réutilisée","Équivalent réutilisation","k unités totales","Total JH"],rows))
parts.append('<p>La taille est un comptage syntaxique reproductible. L’équivalence d’une déclaration JSON/XML/HTML avec une instruction de programme reste une hypothèse : poids 1 dans le cas central, 0,5 à 2 dans les sensibilités. Les tests et le code généré sont exclus de la taille à produire ; leur effort de réalisation/vérification est couvert par le modèle.</p><pre>AA : qualification et assimilation du composant\nIM : effort d’intégration relatif à un composant de même taille\nConception et code des composants réutilisés inchangés : DM = CM = 0\n\nAAM = (AA + 0,3 × IM) / 100\nCas central : AA = 2 ; IM = 5 → AAM = 0,035\nK = [taille métier + AAM × taille réutilisée] / 1 000\nPM = 2,94 × K^1,0997 × PERS × PREX\nJH = PM × 152 / 7 × 1,18\nDélai = 3,67 × PM^0,31794 × 1,25 mois</pre><p><strong>3,5 % est un coefficient de taille équivalente, pas une remise de prix ni un pourcentage directement appliqué aux JH.</strong> Les tailles sont agrégées avant la formule non linéaire. <a href="'+esc(i["cocomo"]["source"])+'">COCOMO II : modèle de réutilisation, équation 4 et paramètres publiés</a>.</p><p>Le facteur 1,18 inclut les phases initiale et de transition selon la distribution par défaut ; 1,25 fait de même pour le calendrier. Les deux sont des hypothèses d’application. Le délai est calculé en sortie ; il ne sert pas à fabriquer les JH et ne constitue pas un engagement d’équipe.</p><h3>Ce qui est mesuré et ce qui est supposé</h3><ul><li><strong>Mesuré :</strong> fichiers et commits, blocs retenus/exclus, instructions et déclarations.</li><li><strong>Supposé :</strong> plateforme disponible, aucun changement de son code, poids du déclaratif, AA/IM, équipe et facteurs d’échelle nominaux.</li><li><strong>Non observé :</strong> charge historique réelle des OSS, productivité d’une future équipe et délai effectivement tenu.</li></ul><p>'+esc(i["reuse"]["no_double_count"])+'</p><p>'+esc(i["reuse"]["owner"])+'</p></section>')
parts.append('<section id="incertitude"><h2>Une fourchette de scénarios, pas un percentile</h2><p><strong>Les bornes sont conditionnelles, avec une incertitude élevée.</strong> Elles combinent les hypothèses ci-dessous ; elles n’ont ni probabilité de couverture ni interprétation P50/P90.</p>')
rows=[]
for s in i["scenarios"]:rows.append([esc(s["label"]),num(s["declarative_weight"],1),num(s["AA"]),num(s["IM"])+' %',num(s["PERS"],2),num(s["PREX"],2),esc(s["assumption"])])
parts.append(table(["Scénario","Poids déclaratif","AA","IM","PERS","PREX","Interprétation"],rows))
parts.append('<p>AA est pris sur l’échelle publiée ; IM reste une hypothèse d’ingénierie. PERS et PREX utilisent les valeurs COCOMO pour capacité/stabilité et expérience de l’équipe. Ces notes ne sont pas des évaluations observées d’une équipe Beaumanoir, eXalt ou OSS. Les autres multiplicateurs et facteurs d’échelle restent nominaux.</p><h3>Effet d’un seul paramètre, les autres au cas central</h3>')
rows=[]
labels={"declarative_weight":"Poids du déclaratif","AA":"Qualification du composant","IM":"Intégration du composant","PERS":"Capacité/stabilité équipe","PREX":"Expérience équipe"}
for axis,label in labels.items():
 rows.append([label]+[num(x["single_parameter_sensitivity"][axis][0])+'–'+num(x["single_parameter_sensitivity"][axis][1])+' JH' for x in r["results"]])
parts.append(table(["Hypothèse variée","ERPNext/Frappe","Odoo","Tryton","Axelor"],rows))
parts.append('<h3>Incertitudes non éliminées</h3><ul>'+''.join('<li>'+esc(x)+'</li>' for x in i["uncertainty"]["remaining"])+'</ul><p>Le rapprochement des quatre résultats ne constitue pas quatre validations indépendantes : ils partagent le même modèle, les mêmes scénarios et plusieurs hypothèses de mesure.</p><h3>Statut des trois méthodes</h3>')
for key in ["cocomo","cosmic","isbsg"]:parts.append('<p><strong>'+key.upper()+' :</strong> '+esc(i["triangulation"][key])+'</p>')
parts.append('</section><section id="activites"><h2>Activités incluses dans chaque total</h2><p>Ventilation centrale selon la distribution par défaut du manuel COCOMO, conservée pour la traçabilité. Ce sont des activités, pas des charges observées par rôle.</p>')
rows=[]
for j,a in enumerate(r["results"][0]["activities_central"]):
 label="Préparation et déploiement" if a["id"]=="deployment" else a["label"]
 rows.append([esc(label),num(a["share"]*100,2)+' %']+[num(x["activities_central"][j]["jh"],1) for x in r["results"]])
rows.append(["<strong>Total</strong>","100 %"]+['<strong>'+num(x["scenarios"]["central"]["total_jh"],1)+' JH</strong>' for x in r["results"]])
parts.append(table(["Activité","Part","ERPNext/Frappe","Odoo","Tryton","Axelor"],rows))
parts.append('<p>Les JH couvrent analyse, conception, développement et tests développeur, QA/évaluation, environnement, pilotage logiciel et déploiement. Une ventilation par rôle demanderait une clé explicite : les activités d’analyse, conception ou QA ne correspondent pas chacune à un seul métier.</p><h3>Délais calculés et conservés</h3>')
rows=[]
for x in r["results"]:rows.append([esc(x["label"])]+[num(x["scenarios"][s]["total_schedule_months"],1)+' mois' for s in ["lower","central","upper"]])
parts.append(table(["Référence","Favorable","Central","Prudent"],rows)+'</section>')
p=r["progress"]
parts.append('<section id="avancement"><h2>Ce qui a progressé et la suite utile</h2><ul><li><strong>4 / 4 estimations natives</strong> sur un contrat commun de <strong>7 rubriques</strong>, avec '+num(v["contract_source_links"])+' liens de preuve.</li><li><strong>'+num(p["measured_files"])+' fichiers mesurés</strong> : '+num(p["new_files"])+' côté fonctions métier, '+num(p["reused_files"])+' côté composants réutilisés. '+num(p["excluded_blocks"])+' blocs ou déclarations hors périmètre sont explicitement retirés.</li><li><strong>Cumul métier : 6 capacités Master Data concernées, BC-002 à BC-007.</strong> Pas de nouvelles capacités ajoutées, ni de prétention à couvrir toutes leurs garanties FLOW.</li><li>Suppression de l’imputation de la construction historique de la plateforme. Qualification et intégration comptées une fois, avec hypothèses visibles.</li><li>'+num(v["active_files_unchanged"])+' fichiers témoins du modèle actif inchangés. Aucun nouveau cumul global Flow ; aucune addition des alternatives.</li></ul><p><strong>L’incertitude de périmètre et de financement a diminué.</strong> La productivité, l’effort d’intégration réel et le périmètre avancé FLOW restent incertains. Les intervalles ne sont pas une calibration historique.</p><div class="note"><strong>Une autre itération vaut le coup.</strong> '+esc(i["next_iteration"])+'</div></section>')
parts.append('<section id="preuves"><h2>Pièces et reproduction</h2><p>Les six dépôts restent figés aux commits du manifeste précédent ; chaque fichier retenu a été comparé à son objet Git. Les compteurs de langage reprennent les parseurs versionnés de cet audit.</p><ul>')
for name,label in [("inputs.json","Contrat, hypothèses et scénarios"),("scope-rules.json","Règles de sélection et exclusions"),("measurements.json","Mesures détaillées et empreintes"),("results.json","Calculs, activités et délais"),("verification.json","Vérifications indépendantes")]:parts.append('<li><a href="'+name+'">'+label+'</a></li>')
parts.append('</ul><pre>python -B audits/2026-10-30-master-data-comparable-reuse/measure.py\npython -B audits/2026-10-30-master-data-comparable-reuse/calculate.py\npython -B audits/2026-10-30-master-data-comparable-reuse/verify.py\npython -B audits/2026-10-30-master-data-comparable-reuse/report.py</pre><p>'+num(v["checks"])+' assertions techniques réussies. Ces contrôles vérifient sources, exclusions et arithmétique ; ils ne démontrent pas une précision historique des JH.</p></section></main><footer>Estimation d’ingénierie avec assistance IA · Pas de revue humaine externe attribuée · Candidat comparatif séparé de l’économie active · Aucun commit ni push.</footer></html>')
(OUT/"index.html").write_text("".join(parts),encoding="utf-8")
print("Rapport comparable généré")
